INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist es wahr, dass ich mit gezielter Kundenansprache nur neue Kunden erreichen kann?', 2, '[{"text": "Nein", "correct": true, "because": "Zielt auf bestehende Interessenten ab"}, {"text": "Ja", "correct": false, "because": "Fokus liegt auf Wiederansprache"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug nutze ich, um Nutzer nach einem Website-Besuch erneut anzusprechen?', 3, '[{"text": "Tracking-Pixel", "correct": true, "because": "Erfasst Nutzerverhalten"}, {"text": "SEO-Tools", "correct": false, "because": "Für organische Suche"}, {"text": "CRM-Backend", "correct": false, "because": "Für Datenmanagement"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kanäle sind für die erneute Kundenansprache effektiv?', 5, '[{"text": "E-Mail", "correct": true, "because": "Personalisierte Ansprache"}, {"text": "Display-Anzeigen", "correct": true, "because": "Visuelle Reichweite"}, {"text": "Datenbank-Backups", "correct": false, "because": "Kein Marketingkanal"}, {"text": "Interne Memos", "correct": false, "because": "Kein Kundenkontakt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Cookies helfen, Nutzer zu verfolgen. b) Sie garantieren Conversions.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Conversions nicht garantiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Planung einer gezielten Kampagne?', 4, '[{"text": "Zielgruppen-Segmentierung", "correct": false, "because": "Entscheidend für Relevanz"}, {"text": "Anzeigenfrequenz", "correct": false, "because": "Vermeidet Überdruss"}, {"text": "Website-Layout", "correct": true, "because": "Kein direkter Kampagnenfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob E-Mails für die Wiederansprache immer personalisiert sein müssen?', 2, '[{"text": "Nein", "correct": true, "because": "Personalisierung hilfreich, aber optional"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Metrik zeigt den Erfolg einer gezielten Anzeigenkampagne?', 4, '[{"text": "Click-Through-Rate", "correct": true, "because": "Misst Engagement"}, {"text": "Server-Uptime", "correct": false, "because": "Technischer Faktor"}, {"text": "Code-Zeilen", "correct": false, "because": "Kein Marketingmaß"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass gezielte Ansprache nur über Google Ads funktioniert. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Auch andere Plattformen wie Facebook"}, {"text": "Ja", "correct": false, "because": "Mehrere Kanäle möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die erneute Ansprache teurer als Erstkampagnen?', 2, '[{"text": "Nein", "correct": true, "because": "Oft kosteneffizienter durch Zielgruppe"}, {"text": "Ja", "correct": false, "because": "Gezielter Einsatz spart Kosten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Daten nutze ich für gezielte E-Mail-Kampagnen?', 4, '[{"text": "Nutzerinteraktionen", "correct": true, "because": "Zeigen Interesse"}, {"text": "Kaufhistorie", "correct": true, "because": "Ermöglicht Personalisierung"}, {"text": "Server-Logs", "correct": false, "because": "Technische Daten"}, {"text": "Zufallszahlen", "correct": false, "because": "Keine Relevanz"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich Nutzer erneut anspreche?', 4, '[{"text": "Relevante Inhalte", "correct": true, "because": "Steigert Engagement"}, {"text": "Hohe Anzeigenanzahl", "correct": false, "because": "Risiko für Überdruss"}, {"text": "Generische Botschaften", "correct": false, "because": "Weniger effektiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Warenkorbabbrüche sind ein Ziel. b) Sie brauchen keine Cookies.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Cookies oft nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine gezielte Kampagne?', 3, '[{"text": "Nutzerdaten", "correct": false, "because": "Basis für Targeting"}, {"text": "Anzeigenplattform", "correct": false, "because": "Ermöglicht Auslieferung"}, {"text": "Firmenfarben", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, wie ich Nutzer nach Warenkorbabbruch anspreche?', 4, '[{"text": "Personalisierte E-Mail mit Rabatt", "correct": true, "because": "Fördert Conversion"}, {"text": "Generische Banner", "correct": false, "because": "Weniger effektiv"}, {"text": "Keine Aktion", "correct": false, "because": "Verpasst Chance"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass gezielte Ansprache immer nervt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Bei guter Umsetzung effektiv"}, {"text": "Ja", "correct": false, "because": "Frequenz steuerbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip hilft, Anzeigenüberdruss zu vermeiden?', 3, '[{"text": "Frequenzbegrenzung", "correct": true, "because": "Schont Nutzer"}, {"text": "Maximale Reichweite", "correct": false, "because": "Risiko für Überdruss"}, {"text": "Zufällige Inhalte", "correct": false, "because": "Weniger relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Erhöht gezielte Ansprache die Conversion-Rate?', 2, '[{"text": "Ja", "correct": true, "because": "Fokussiert Interessenten"}, {"text": "Nein", "correct": false, "because": "Höhere Relevanz wirkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Plattformen eignen sich für gezielte Anzeigen?', 5, '[{"text": "Google Ads", "correct": true, "because": "Breite Reichweite"}, {"text": "Facebook", "correct": true, "because": "Genaue Zielgruppen"}, {"text": "Texteditor", "correct": false, "because": "Kein Ad-Tool"}, {"text": "VPN-Dienst", "correct": false, "because": "Kein Marketingkanal"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der erneuten Ansprache unwichtig?', 3, '[{"text": "Anzeigenrelevanz", "correct": false, "because": "Steigert Engagement"}, {"text": "Zielgruppensegmentierung", "correct": false, "because": "Fokussiert Kampagne"}, {"text": "Social-Media-Follower", "correct": true, "because": "Kein direkter Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie gehe ich vor, wenn ich Nutzer nach einem Besuch erneut anspreche?', 4, '[{"text": "Zielgruppenliste erstellen und Ads schalten", "correct": true, "because": "Gezielte Ansprache"}, {"text": "Zufällige E-Mails senden", "correct": false, "because": "Ineffizient"}, {"text": "Website neu gestalten", "correct": false, "because": "Kein direkter Ansatz"}]');
